1	import * as ADNotations from "@antimatter-dimensions/notations";
2	
3	export const Notation = (function() {
4	  const N = ADNotations;
5	  const notation = type => {
6	    const n = new type();
7	    n.setAsCurrent = () => {
8	      player.options.notation = n.name;
9	      ui.notationName = n.name;
10	    };
11	    return n;
12	  };
13	  const painful = n => {
14	    n.isPainful = true;
15	    return n;
